  const LEAD_TO = { name: 'Name', first: 'First name', last: 'Last name', email: 'Email', phone: 'Phone', company: 'Company', address: 'Address', city: 'City', message: 'Message', source: 'Source', note: 'Note (as “field: value”)', ignore: 'Leave out' };
