    const keyForm = [h('p', { class: 'day-hint' }, 'In Postiz, copy the key from Settings → Public API.'), h('label', {}, 'API key', key), h('label', {}, 'Your own Postiz address (optional)', url), h('div', { class: 'btns' }, go)];
